// ListPlanEvents pages a plan's events by sequence ascending, starting after
// the given sequence. The optional node and run filters are
// empty-string-means-absent; a NULL row_limit is LIMIT ALL.
func (q *Queries) ListPlanEvents(ctx context.Context, arg ListPlanEventsParams) ([][]byte, error) {
	rows, err := q.db.Query(ctx, listPlanEvents,
		arg.PlanID,
		arg.AccountID,
		arg.ProjectID,
		arg.Sequence,
		arg.NodeID,
		arg.RunID,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items [][]byte
	for rows.Next() {
		var event_json []byte
		if err := rows.Scan(&event_json); err != nil {
			return nil, err
		}
		items = append(items, event_json)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

