const listPlanRefs = `-- name: ListPlanRefs :many

SELECT plan_id, account_id, project_id
FROM plans
WHERE ($1::text = '' OR account_id = $1::text)
  AND ($2::text = '' OR project_id = $2::text)
  AND (COALESCE(cardinality($3::text[]), 0) = 0
       OR lifecycle_state = ANY($3::text[]))
  AND ($4::timestamptz IS NULL OR updated_at > $4::timestamptz)
ORDER BY updated_at ASC, plan_id ASC
LIMIT $5::bigint
`

type ListPlanRefsParams struct {
	AccountID       string
	ProjectID       string
	LifecycleStates []string
	UpdatedAfter    pgtype.Timestamptz
	RowLimit        pgtype.Int8
}

type ListPlanRefsRow struct {
	PlanID    string
	AccountID string
	ProjectID string
}

// RunPlan aggregate persistence: the plans row holds the spec and status
// documents, plan_nodes holds one status document per node, and plan_events
// is the append-only, idempotency-keyed event stream. Sequence allocation
// and the create/append idempotency protocols live in the repository; these
// statements are the SQL they drive.
// ListPlanRefs lists plan references matching the scope filters, oldest
// update first. Optional text filters are empty-string-means-absent; an
// empty lifecycle state array disables that predicate; a NULL updated_after
// or row_limit is "no bound".
func (q *Queries) ListPlanRefs(ctx context.Context, arg ListPlanRefsParams) ([]ListPlanRefsRow, error) {
	rows, err := q.db.Query(ctx, listPlanRefs,
		arg.AccountID,
		arg.ProjectID,
		arg.LifecycleStates,
		arg.UpdatedAfter,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListPlanRefsRow
	for rows.Next() {
		var i ListPlanRefsRow
		if err := rows.Scan(&i.PlanID, &i.AccountID, &i.ProjectID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listRecoverablePlanCommands = `-- name: ListRecoverablePlanCommands :many
SELECT command_id,
       plan_id,
       actor_id,
       action,
       idempotency_key,
       payload_json,
       status,
       failure_reason,
       created_at,
       updated_at,
       account_id,
       project_id
FROM plan_commands
WHERE (COALESCE(cardinality($1::text[]), 0) = 0
       OR status = ANY($1::text[]))
  AND ($2::text = '' OR plan_id = $2::text)
  AND ($3::text = '' OR account_id = $3::text)
  AND ($4::text = '' OR project_id = $4::text)
  AND ($5::text = '' OR action = $5::text)
ORDER BY updated_at ASC, command_id ASC
LIMIT $6::bigint
`

type ListRecoverablePlanCommandsParams struct {
	Statuses  []string
	PlanID    string
	AccountID string
	ProjectID string
	Action    string
	RowLimit  pgtype.Int8
}

// ListRecoverablePlanCommands lists commands in the recoverable states
// oldest-update-first. An empty status array disables that predicate; the
// plan/account/project/action filters are empty-string-means-absent; a NULL
// row_limit is LIMIT ALL.
func (q *Queries) ListRecoverablePlanCommands(ctx context.Context, arg ListRecoverablePlanCommandsParams) ([]PlanCommand, error) {
	rows, err := q.db.Query(ctx, listRecoverablePlanCommands,
		arg.Statuses,
		arg.PlanID,
		arg.AccountID,
		arg.ProjectID,
		arg.Action,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []PlanCommand
	for rows.Next() {
		var i PlanCommand
		if err := rows.Scan(
			&i.CommandID,
			&i.PlanID,
			&i.ActorID,
			&i.Action,
			&i.IdempotencyKey,
			&i.PayloadJson,
			&i.Status,
			&i.FailureReason,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.AccountID,
			&i.ProjectID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

